draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    ctx.save();
    ctx.translate(W/2, H/2);
    ctx.rotate(i * Math.PI / 2.5 + t);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, 50 + 20 * Math.sin(t));
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, 50 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.restore();
  }
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Rich in Vit C', W/2, H/2 - 80);
  ctx.fillText('Full of Fiber', W/2, H/2 + 80);
  ctx.restore();
}
